#pragma once

// A tile-free Canvas page keeps the access-point-only Web UI light.
constexpr char productionTrackPageJapanese[] = R"HTML(
<!doctype html>
<html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>航跡・ウェイポイント</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#18202a;font:16px system-ui,sans-serif}main{max-width:760px;margin:auto;padding:16px}h1{font-size:22px;margin:4px 0 8px}a{color:#1859a8;font-weight:700}.hint,.panel{border:1px solid #d7dce2;border-radius:10px;background:#fff;padding:13px;margin-top:12px}.hint{background:#f2f5f8;color:#53606e;font-size:14px;line-height:1.5}.title{font-weight:800;margin-bottom:7px}.canvas-wrap{height:218px;border-radius:8px;overflow:hidden;background:#e8f1f7}.local .canvas-wrap{height:260px}canvas{width:100%;height:100%;display:block;touch-action:manipulation}.row{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:10px}button{min-height:43px;border:0;border-radius:8px;font:700 15px system-ui;background:#dbe1e7;color:#18202a}button.primary{background:#2563eb;color:#fff}button.danger{background:#c92532;color:#fff}.stats,.message{font-size:14px;color:#53606e;font-variant-numeric:tabular-nums;margin-top:8px}.list{margin-top:10px;max-height:180px;overflow:auto}.wp{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;border-top:1px solid #e2e5e9;padding:8px 0;font-size:14px}.wp button{min-height:34px;padding:0 11px;font-size:13px}.placing{outline:3px solid #f0a51c}
</style>
<main>
<a href="/">← 制御画面へ戻る</a><h1>GNSS 航跡・ウェイポイント</h1>
<div id="state" class="hint">GNSSを待っています。</div>
<section class="panel"><div class="title">全体（2分ごとの粗い航跡）</div><div class="canvas-wrap"><canvas id="overview"></canvas></div><div id="overview-stats" class="stats"></div></section>
<section class="panel local"><div class="title">現在地周辺（現在地を中央に固定）</div><div class="canvas-wrap"><canvas id="local"></canvas></div><div id="local-stats" class="stats"></div></section>
<section class="panel"><div class="title">ウェイポイント</div><div class="hint">「追加」を押してから、上または下の地図をタップします。制御中は変更できません。</div><div class="row"><button id="add" class="primary">ウェイポイントを追加</button><button id="reset-track" class="danger">航跡をリセット</button></div><div class="row"><button id="clear-wp">全ウェイポイントを削除</button><a href="/"><button style="width:100%">制御画面で使用する</button></a></div><div id="waypoints" class="list"></div><div id="message" class="message"></div></section>
</main>
<script>
const $=id=>document.getElementById(id);let data={history:[],current:null,waypoints:[],revision:0,local_radius_m:50};let placing=false;
function valid(p){return Array.isArray(p)&&Number.isFinite(Number(p[0]))&&Number.isFinite(Number(p[1]));}
function meter(lat,lon,lat0,lon0){const k=111320,r=Math.PI/180;return{x:(lon-lon0)*k*Math.cos(lat0*r),y:(lat-lat0)*k};}
function ctxFor(c){const r=devicePixelRatio||1,w=Math.max(1,c.clientWidth),h=Math.max(1,c.clientHeight);if(c.width!==Math.round(w*r)||c.height!==Math.round(h*r)){c.width=Math.round(w*r);c.height=Math.round(h*r)}const x=c.getContext('2d');x.setTransform(r,0,0,r,0,0);return{x,w,h};}
function dot(x,p,map,color,size){x.fillStyle=color;x.beginPath();const q=map(p);x.arc(q[0],q[1],size,0,Math.PI*2);x.fill();}
function course(p){return valid(p)&&typeof p[2]==='number'&&Number.isFinite(p[2])?p[2]:null;}
function currentMarker(x,p,map){const q=map(p),c=course(p);if(c===null){dot(x,p,map,'#127b37',7);return}x.save();x.translate(q[0],q[1]);x.rotate(c);x.fillStyle='#127b37';x.beginPath();x.moveTo(0,-12);x.lineTo(7,9);x.lineTo(0,5);x.lineTo(-7,9);x.closePath();x.fill();x.restore();}
function trail(x,points,map){if(!points.length)return;x.strokeStyle='#397ab6';x.lineWidth=2;x.beginPath();points.forEach((p,i)=>{const q=map(p);i?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1])});x.stroke();}
function overallBounds(){const p=[...data.history,...data.waypoints];if(valid(data.current))p.push(data.current);if(!p.length)return null;let a=p[0][0],b=a,c=p[0][1],d=c;p.forEach(q=>{a=Math.min(a,q[0]);b=Math.max(b,q[0]);c=Math.min(c,q[1]);d=Math.max(d,q[1])});const lat=(a+b)/2,lon=(c+d)/2,z=Math.max(20,(b-a)*111320/2+12,(d-c)*111320*Math.cos(lat*Math.PI/180)/2+12);return{lat,lon,z};}
function drawOverview(){const c=$('overview'),o=ctxFor(c),x=o.x,b=overallBounds();x.fillStyle='#e8f1f7';x.fillRect(0,0,o.w,o.h);if(!b){x.fillStyle='#53606e';x.fillText('有効なGNSS位置を待っています',14,28);return}const map=p=>{const q=meter(p[0],p[1],b.lat,b.lon);return[(q.x/b.z*.45+.5)*o.w,(-q.y/b.z*.45+.5)*o.h]};x.strokeStyle='#c3d2dc';x.strokeRect(0,0,o.w,o.h);trail(x,data.history,map);data.waypoints.forEach((p,i)=>{dot(x,p,map,'#c52832',6);const q=map(p);x.fillStyle='#7d1820';x.fillText(String(i+1),q[0]+7,q[1]-6)});if(valid(data.current))currentMarker(x,data.current,map);x.fillStyle='#53606e';x.fillText('北 ↑',8,18);}
function drawLocal(){const c=$('local'),o=ctxFor(c),x=o.x;x.fillStyle='#e8f1f7';x.fillRect(0,0,o.w,o.h);if(!valid(data.current)){x.fillStyle='#53606e';x.fillText('有効なGNSS位置を待っています',14,28);return}const origin=data.current,z=Number(data.local_radius_m)||50,map=p=>{const q=meter(p[0],p[1],origin[0],origin[1]);return[(q.x/z*.45+.5)*o.w,(-q.y/z*.45+.5)*o.h]};x.strokeStyle='#c3d2dc';x.strokeRect(0,0,o.w,o.h);data.waypoints.forEach((p,i)=>{const q=meter(p[0],p[1],origin[0],origin[1]);if(Math.abs(q.x)<=z*1.2&&Math.abs(q.y)<=z*1.2){dot(x,p,map,'#c52832',6);const t=map(p);x.fillStyle='#7d1820';x.fillText(String(i+1),t[0]+7,t[1]-6)}});currentMarker(x,origin,map);x.fillStyle='#53606e';x.fillText('北 ↑ / ±'+z+' m',8,18);}
function render(){drawOverview();drawLocal();const hasCourse=course(data.current)!==null;$('overview-stats').textContent='粗い航跡 '+data.history.length+' 点 / 緑'+(hasCourse?'矢印が進行方向':'点が最新位置');$('local-stats').textContent=valid(data.current)?(hasCourse?'現在地を中心に固定。緑矢印はGNSS進行方向です。':'現在地を中心に固定。進行方向を計算中です。'):'GNSS位置がまだありません。';$('state').textContent=valid(data.current)?'最新位置: '+Number(data.current[0]).toFixed(7)+', '+Number(data.current[1]).toFixed(7)+'　/ 進行方向 '+(hasCourse?'推定済み':'未確定（GNSS位置を収集中）'):'GNSSの有効な位置を待っています。';$('waypoints').innerHTML=data.waypoints.length?data.waypoints.map((p,i)=>'<div class="wp"><span>'+String(i+1)+'. '+Number(p[0]).toFixed(7)+', '+Number(p[1]).toFixed(7)+'</span><button data-i="'+i+'">削除</button></div>').join(''):'ウェイポイントはありません。';document.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>post('/api/track/waypoints?action=delete&index='+b.dataset.i));}
async function load(full){try{const r=await fetch('/api/track'+(full?'':'?since='+data.revision),{cache:'no-store'});if(!r.ok)throw Error();const v=await r.json();if(v.changed){data.history=v.history||[];data.waypoints=v.waypoints||[]}data.current=v.current||null;data.revision=v.revision||data.revision;data.local_radius_m=v.local_radius_m||50;render()}catch(e){$('state').textContent='通信側XIAOから航跡を取得できません。'}}
async function post(url){try{const r=await fetch(url,{method:'POST'}),v=await r.json();$('message').textContent=v.message||'';if(r.ok)load(true)}catch(e){$('message').textContent='変更を送信できませんでした。'}}
function place(c,e,local){if(!placing)return;const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;let lat,lon;if(local){if(!valid(data.current))return;const z=Number(data.local_radius_m)||50;lat=data.current[0]+(.5-y)*z/.45/111320;lon=data.current[1]+(x-.5)*z/.45/(111320*Math.cos(data.current[0]*Math.PI/180));}else{const b=overallBounds();if(!b)return;lat=b.lat+(.5-y)*b.z/.45/111320;lon=b.lon+(x-.5)*b.z/.45/(111320*Math.cos(b.lat*Math.PI/180));}placing=false;$('add').classList.remove('placing');post('/api/track/waypoints?action=add&lat='+encodeURIComponent(lat)+'&lon='+encodeURIComponent(lon));}
$('add').onclick=()=>{placing=!placing;$('add').classList.toggle('placing',placing);$('message').textContent=placing?'地図をタップして配置してください。':''};$('reset-track').onclick=()=>{if(confirm('航跡だけを消去します。ウェイポイントは残ります。'))post('/api/track/reset')};$('clear-wp').onclick=()=>{if(confirm('全ウェイポイントを削除します。'))post('/api/track/waypoints?action=clear')};$('overview').onclick=e=>place($('overview'),e,false);$('local').onclick=e=>place($('local'),e,true);window.addEventListener('resize',render);setInterval(()=>load(false),5000);load(true);
</script>
</html>
)HTML";
